34	/*
35	 * Ensure that any exponent, if present, is at least MIN_EXPONENT_DIGITS
36	 * in length.
37	 */
38	static void
39	ensure_minimum_exponent_length(char* buffer, size_t buf_size)
40	{
41	    char *p = strpbrk(buffer, "eE");
42	    if (p && (*(p + 1) == '-' || *(p + 1) == '+')) {
43	        char *start = p + 2;
44	        int exponent_digit_cnt = 0;
45	        int leading_zero_cnt = 0;
46	        int in_leading_zeros = 1;
47	        int significant_digit_cnt;
48	
49	        /* Skip over the exponent and the sign. */
50	        p += 2;
51	
52	        /* Find the end of the exponent, keeping track of leading zeros. */
53	        while (*p && isdigit(Py_CHARMASK(*p))) {
54	            if (in_leading_zeros && *p == '0') {
55	                ++leading_zero_cnt;
56	            }
57	            if (*p != '0') {
58	                in_leading_zeros = 0;
59	            }
60	            ++p;
61	            ++exponent_digit_cnt;
62	        }
63	
64	        significant_digit_cnt = exponent_digit_cnt - leading_zero_cnt;
65	        if (exponent_digit_cnt == MIN_EXPONENT_DIGITS) {
66	            /*
67	             * If there are 2 exactly digits, we're done,
68	             * regardless of what they contain
69	             */
70	        }
71	        else if (exponent_digit_cnt > MIN_EXPONENT_DIGITS) {
72	            int extra_zeros_cnt;
73	
74	            /*
75	             * There are more than 2 digits in the exponent.  See
76	             * if we can delete some of the leading zeros
77	             */
78	            if (significant_digit_cnt < MIN_EXPONENT_DIGITS) {
79	                significant_digit_cnt = MIN_EXPONENT_DIGITS;
80	            }
81	            extra_zeros_cnt = exponent_digit_cnt - significant_digit_cnt;
82	
83	            /*
84	             * Delete extra_zeros_cnt worth of characters from the
85	             * front of the exponent
86	             */
87	            assert(extra_zeros_cnt >= 0);
88	
89	            /*
90	             * Add one to significant_digit_cnt to copy the
91	             * trailing 0 byte, thus setting the length
92	             */
93	            memmove(start, start + extra_zeros_cnt, significant_digit_cnt + 1);
94	        }
95	        else {
96	            /*
97	             * If there are fewer than 2 digits, add zeros
98	             * until there are 2, if there's enough room
99	             */
100	            int zeros = MIN_EXPONENT_DIGITS - exponent_digit_cnt;
101	            if (start + zeros + exponent_digit_cnt + 1 < buffer + buf_size) {
102	                memmove(start + zeros, start, exponent_digit_cnt + 1);
103	                memset(start, '0', zeros);
104	            }
105	        }
106	    }
107	}
