540	            while (NumPyOS_ascii_isalnum(*p) || *p == '_') {
541	                ++p;
542	            }
543	            if (*p == ')') {
544	                ++p;
545	            }
546	        }
547	        if (endptr != NULL) {
548	            *endptr = (char*)p;
549	        }
550	        return NPY_NAN;
551	    }
552	    else if (NumPyOS_ascii_strncasecmp(p, "inf", 3) == 0) {
553	        p += 3;
554	        if (NumPyOS_ascii_strncasecmp(p, "inity", 5) == 0) {
555	            p += 5;
556	        }
557	        if (endptr != NULL) {
558	            *endptr = (char*)p;
559	        }
560	        return result*NPY_INFINITY;
561	    }
562	    /* End of ##1 */
563	
564	#ifdef HAVE_STRTOLD_L
565	    clocale = newlocale(LC_ALL_MASK, "C", NULL);
566	    if (clocale) {
567	        errno = 0;
568	        result = strtold_l(s, endptr, clocale);
569	        freelocale(clocale);
570	    }
571	    else {
572	        if (endptr != NULL) {
573	            *endptr = (char*)s;
574	        }
575	        result = 0;
576	    }
577	    return result;
578	#else
579	    return NumPyOS_ascii_strtod(s, endptr);
580	#endif
581	}
582	
583	/*
584	 * read_numberlike_string:
585	 *      * fp: FILE pointer
586	 *      * value: Place to store the value read
587	 *
588	 * Read what looks like valid numeric input and store it in a buffer
589	 * for later parsing as a number.
590	 *
591	 * Similarly to fscanf, this function always consumes leading whitespace,
592	 * and any text that could be the leading part in valid input.
593	 *
594	 * Return value: similar to fscanf.
595	 *      * 0 if no number read,
596	 *      * 1 if a number read,
597	 *      * EOF if end-of-file met before reading anything.
598	 */
599	static int
600	read_numberlike_string(FILE *fp, char *buffer, size_t buflen)
601	{
602	
603	    char *endp;
604	    char *p;
605	    int c;
606	    int ok;
607	
608	    /*
609	     * Fill buffer with the leftmost matching part in regexp
610	     *
611	     *     \s*[+-]? ( [0-9]*\.[0-9]+([eE][+-]?[0-9]+)
612	     *              | nan  (  \([:alphanum:_]*\) )?
613	     *              | inf(inity)?
614	     *              )
615	     *
616	     * case-insensitively.
617	     *
618	     * The "do { ... } while (0)" wrapping in macros ensures that they behave
619	     * properly eg. in "if ... else" structures.
620	     */
621	
622	#define END_MATCH()                                                         \
623	        goto buffer_filled
624	
625	#define NEXT_CHAR()                                                         \
626	        do {                                                                \
627	            if (c == EOF || endp >= buffer + buflen - 1)            \
628	                END_MATCH();                                                \
629	            *endp++ = (char)c;                                              \
630	            c = getc(fp);                                                   \
631	        } while (0)
632	
633	#define MATCH_ALPHA_STRING_NOCASE(string)                                   \
634	        do {                                                                \
635	            for (p=(string); *p!='\0' && (c==*p || c+('a'-'A')==*p); ++p)   \
636	                NEXT_CHAR();                                                \
637	            if (*p != '\0') END_MATCH();                                    \
638	        } while (0)
639	
640	#define MATCH_ONE_OR_NONE(condition)                                        \
641	        do { if (condition) NEXT_CHAR(); } while (0)
642	
643	#define MATCH_ONE_OR_MORE(condition)                                        \
644	        do {                                                                \
645	            ok = 0;                                                         \
646	            while (condition) { NEXT_CHAR(); ok = 1; }                      \
647	            if (!ok) END_MATCH();                                           \
648	        } while (0)
649	
650	#define MATCH_ZERO_OR_MORE(condition)                                       \
651	        while (condition) { NEXT_CHAR(); }
652	
653	    /* 1. emulate fscanf EOF handling */
654	    c = getc(fp);
655	    if (c == EOF) {
656	        return EOF;
657	    }
658	    /* 2. consume leading whitespace unconditionally */
659	    while (NumPyOS_ascii_isspace(c)) {
660	        c = getc(fp);
661	    }
662	
663	    /* 3. start reading matching input to buffer */
664	    endp = buffer;
665	
666	    /* 4.1 sign (optional) */
667	    MATCH_ONE_OR_NONE(c == '+' || c == '-');
668	
669	    /* 4.2 nan, inf, infinity; [case-insensitive] */
670	    if (c == 'n' || c == 'N') {
671	        NEXT_CHAR();
672	        MATCH_ALPHA_STRING_NOCASE("an");
673	
674	        /* accept nan([:alphanum:_]*), similarly to strtod */
675	        if (c == '(') {
676	            NEXT_CHAR();
677	            MATCH_ZERO_OR_MORE(NumPyOS_ascii_isalnum(c) || c == '_');
678	            if (c == ')') {
679	                NEXT_CHAR();
680	            }
681	        }
682	        END_MATCH();
683	    }
684	    else if (c == 'i' || c == 'I') {
685	        NEXT_CHAR();
686	        MATCH_ALPHA_STRING_NOCASE("nfinity");
687	        END_MATCH();
688	    }
689	
690	    /* 4.3 mantissa */
691	    MATCH_ZERO_OR_MORE(NumPyOS_ascii_isdigit(c));
692	
693	    if (c == '.') {
694	        NEXT_CHAR();
695	        MATCH_ONE_OR_MORE(NumPyOS_ascii_isdigit(c));
696	    }
697	
698	    /* 4.4 exponent */
699	    if (c == 'e' || c == 'E') {
700	        NEXT_CHAR();
701	        MATCH_ONE_OR_NONE(c == '+' || c == '-');
702	        MATCH_ONE_OR_MORE(NumPyOS_ascii_isdigit(c));
703	    }
704	
705	    END_MATCH();
706	
707	buffer_filled:
708	
709	    ungetc(c, fp);
710	    *endp = '\0';
711	
712	    /* return 1 if something read, else 0 */
713	    return (buffer == endp) ? 0 : 1;
714	}
715	
716	#undef END_MATCH
717	#undef NEXT_CHAR
718	#undef MATCH_ALPHA_STRING_NOCASE
719	#undef MATCH_ONE_OR_NONE
720	#undef MATCH_ONE_OR_MORE
721	#undef MATCH_ZERO_OR_MORE
722	
723	/*
724	 * NumPyOS_ascii_ftolf:
725	 *      * fp: FILE pointer
726	 *      * value: Place to store the value read
727	 *
728	 * Similar to PyOS_ascii_strtod, except that it reads input from a file.
729	 *
730	 * Similarly to fscanf, this function always consumes leading whitespace,
731	 * and any text that could be the leading part in valid input.
732	 *
733	 * Return value: similar to fscanf.
734	 *      * 0 if no number read,
735	 *      * 1 if a number read,
736	 *      * EOF if end-of-file met before reading anything.
737	 */
738	NPY_NO_EXPORT int
739	NumPyOS_ascii_ftolf(FILE *fp, double *value)
740	{
741	    char buffer[FLOAT_FORMATBUFLEN + 1];
742	    char *p;
743	    int r;
744	
745	    r = read_numberlike_string(fp, buffer, FLOAT_FORMATBUFLEN+1);
746	
747	    if (r != EOF && r != 0) {
748	        *value = NumPyOS_ascii_strtod(buffer, &p);
749	        r = (p == buffer) ? 0 : 1;
750	    }
751	    return r;
752	}
753	
754	NPY_NO_EXPORT int
755	NumPyOS_ascii_ftoLf(FILE *fp, long double *value)
756	{
757	    char buffer[FLOAT_FORMATBUFLEN + 1];
758	    char *p;
759	    int r;
760	
761	    r = read_numberlike_string(fp, buffer, FLOAT_FORMATBUFLEN+1);
762	
763	    if (r != EOF && r != 0) {
764	        *value = NumPyOS_ascii_strtold(buffer, &p);
765	        r = (p == buffer) ? 0 : 1;
766	    }
767	    return r;
768	}
769	
770	NPY_NO_EXPORT npy_longlong
771	NumPyOS_strtoll(const char *str, char **endptr, int base)
772	{
773	    return strtoll(str, endptr, base);
774	}
775	
776	NPY_NO_EXPORT npy_ulonglong
777	NumPyOS_strtoull(const char *str, char **endptr, int base)
778	{
779	    return strtoull(str, endptr, base);
780	}
